-- PT117-S3-Q3. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT117-S3-Q3$batch09$ AND q.stimulus=$batch09$Chairperson: The board of directors of our corporation should not allow the incentives being offered by two foreign governments to entice us to expand our operations into their countries without further consideration of the issue. Although there is an opportunity to increase our profits by expanding our operations there, neither of these countries is politically stable.$batch09$ AND q.prompt=$batch09$The chairperson's reasoning most closely conforms to which one of the following principles?$batch09$ AND q.correct_choice=$batch09$D$batch09$) THEN RAISE EXCEPTION 'Question changed: PT117-S3-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT117-S3-Q3$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT117-S3-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT117-S3-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$The board shouldn't let the foreign incentives entice it into expanding there without further consideration.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$Expanding could raise profits, but neither country is politically stable.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$Look at how modest the conclusion is. The chairperson doesn't say "don't expand." They say "don't jump in without thinking it over." Instability is a reason for caution, weighed against the chance at profit. A principle that forbids expansion or ranks stability above everything is stronger than this argument.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Be cautious about expanding into politically unstable countries.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT117-S3-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This is the trap, picked by 11%. "Never expand" would settle the matter, but the chairperson only asks for further consideration. That leaves room to expand after all. A rule that forbids expansion outright goes further than the reasoning does.$batch09$), ($batch09$B$batch09$, $batch09$This pushes toward expanding wherever there's profit. The chairperson is putting on the brakes.$batch09$), ($batch09$C$batch09$, $batch09$This is the second trap, at 6%. The chairperson raises stability as a concern but never ranks it as the most important factor. They even acknowledge the profit opportunity.$batch09$), ($batch09$D$batch09$, $batch09$"Be cautious" matches "not without further consideration," and "politically unstable countries" matches the evidence. This is the principle at exactly the argument's strength.$batch09$), ($batch09$E$batch09$, $batch09$The chairperson says not to let incentives alone entice the board. That isn't the same as always ignoring incentives.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT117-S3-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
